class Node {
  constructor(value, level) {
    this.value = value;
    // Array of next pointers for each level
    this.forward = new Array(level + 1).fill(null);
  }
}

class SkipList {
  constructor(maxLevel = 16, p = 0.5) {
    this.maxLevel = maxLevel;
    this.p = p; // Probability of level promotion
    this.level = 0;
    this.head = new Node(-Infinity, maxLevel);
  }

  // Randomly determine level for a new node
  randomLevel() {
    let level = 0;
    while (Math.random() < this.p && level < this.maxLevel) {
      level++;
    }
    return level;
  }

  // Insert a value into the skip list
  insert(value) {
    const update = new Array(this.maxLevel + 1).fill(null);
    let current = this.head;

    // Find position to insert at each level
    for (let i = this.level; i >= 0; i--) {
      while (current.forward[i] !== null && current.forward[i].value < value) {
        current = current.forward[i];
      }
      update[i] = current;
    }

    // Get a random level for the new node
    const newLevel = this.randomLevel();

    // Update the list's max level if needed
    if (newLevel > this.level) {
      for (let i = this.level + 1; i <= newLevel; i++) {
        update[i] = this.head;
      }
      this.level = newLevel;
    }

    // Create new node
    const newNode = new Node(value, newLevel);

    // Insert the node at all levels
    for (let i = 0; i <= newLevel; i++) {
      newNode.forward[i] = update[i].forward[i];
      update[i].forward[i] = newNode;
    }
  }

  // Search for a value in the skip list
  search(value) {
    let current = this.head;

    // Start from the highest level and work down
    for (let i = this.level; i >= 0; i--) {
      while (current.forward[i] !== null && current.forward[i].value < value) {
        current = current.forward[i];
      }
    }

    // Move to the next node at level 0
    current = current.forward[0];

    // Check if we found the value
    return current !== null && current.value === value;
  }

  // Print the skip list structure
  print() {
    console.log('Skip List Structure:');
    for (let i = this.level; i >= 0; i--) {
      let output = `Level ${i}: `;
      let node = this.head.forward[i];
      while (node !== null) {
        output += `${node.value} -> `;
        node = node.forward[i];
      }
      output += 'null';
      console.log(output);
    }
  }
}

// Example usage
const list = new SkipList();
list.insert(3);
list.insert(6);
list.insert(7);
list.insert(9);
list.insert(12);
list.insert(19);
list.insert(17);
list.insert(26);
list.insert(21);
list.insert(25);
list.print();

console.log('Search for 19:', list.search(19));
console.log('Search for 11:', list.search(11));
